from jsonb_to_recordset($json$[{"id":"che-pe-126","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lanthanoids and actinoids are written as two separate rows beneath the main table so that","options":["they are excluded from the periodic law","the 18-column long form remains compact","they can be treated as noble gases","their atomic numbers can be ignored"],"answer_index":1,"explanation":"Inserting fourteen extra cells into periods 6 and 7 would make those rows awkwardly wide.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-127","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The fourteen lanthanoids still belong chemically to which period of the long form table?","options":["period 4","period 5","period 6","period 7"],"answer_index":2,"explanation":"They follow lanthanum in period 6; actinoids similarly belong to period 7.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-128","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Moseley found that the square root of the characteristic X-ray frequency varies linearly with atomic number as $\\sqrt{\\nu}=a(Z-b)$. This showed that","options":["atomic mass is still the fundamental index","Z, not A, is the property that orders the elements","neutrons determine chemical behaviour","X-rays arise from valence-shell jumps only"],"answer_index":1,"explanation":"A plot of $\\sqrt{\\nu}$ against Z is a straight line; plots against atomic mass are irregular, so Z is the true periodic argument.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-129","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Alkali metals and alkaline earth metals together constitute the","options":["p-block","s-block","d-block","f-block"],"answer_index":1,"explanation":"Their differentiating electron enters the ns subshell (groups 1 and 2).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-130","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The p-block of the long form table begins at boron and ends at","options":["the alkaline earth metals","the noble gases of each period","the lanthanoids","hydrogen only"],"answer_index":1,"explanation":"Groups 13–18 are p-block; the last member of each of these periods is a noble gas.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-131","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"d-block elements are those whose differentiating electron enters a","options":["ns subshell","np subshell","penultimate (n−1)d subshell","(n−2)f subshell"],"answer_index":2,"explanation":"That is the definition of the transition series occupying groups 3–12.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-132","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lanthanoids and actinoids together constitute the","options":["s-block","p-block","d-block","f-block"],"answer_index":3,"explanation":"Their differentiating electron enters the (n−2)f subshell; they are the inner transition elements.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-133","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Hydrogen and helium are the only two members of the","options":["second period","first period","d-block","halogen family"],"answer_index":1,"explanation":"Period 1 fills the 1s subshell and therefore contains just H and He.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-134","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A short period of eight members starts at lithium and ends at","options":["argon","neon","sodium","fluorine"],"answer_index":1,"explanation":"Period 2 fills 2s and 2p (2 + 6 = 8 elements) from Li to Ne.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-135","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Sodium through argon form the second short period, matching the length of the","options":["lithium–neon row","potassium–krypton row","scandium–zinc row","cerium–lutetium row"],"answer_index":0,"explanation":"Period 3 also has eight elements (3s and 3p); 3d is not yet available.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-136","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Filling of 4s, 3d and 4p subshells produces the first long period of","options":["eight elements","ten elements","eighteen elements","thirty-two elements"],"answer_index":2,"explanation":"2 + 10 + 6 = 18 elements from potassium to krypton.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-137","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Group 1 elements other than hydrogen are collectively called","options":["alkaline earth metals","alkali metals","chalcogens","pnictogens"],"answer_index":1,"explanation":"Li, Na, K, Rb, Cs and Fr are the alkali metals.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-138","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Beryllium, magnesium, calcium, strontium, barium and radium are the","options":["alkali metals","alkaline earth metals","halogens","coinage metals"],"answer_index":1,"explanation":"They form group 2 and have the valence configuration ns².","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-139","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine, chlorine, bromine, iodine and astatine belong to the","options":["noble-gas family","halogen family","alkali-metal family","coinage-metal family"],"answer_index":1,"explanation":"Group 17 elements are the halogens (salt-formers).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-140","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Neon, argon, krypton, xenon and radon occupy the","options":["first vertical column","last vertical column of the long form table","f-block","middle of the d-block"],"answer_index":1,"explanation":"They are the noble gases of group 18 (helium is also placed there).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-141","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Main-group (representative) elements are those belonging to the","options":["d-block only","s- and p-blocks","f-block only","inner transition series"],"answer_index":1,"explanation":"s- and p-block elements have their last electron in an ns or np orbital and show the classic group valences.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-142","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"An element is classed as a transition metal if it has an incomplete d subshell in the","options":["nucleus","free atom or in any of its common ions","noble-gas core only","f subshell exclusively"],"answer_index":1,"explanation":"IUPAC uses the incomplete-(n−1)d criterion; Zn²⁺ (d¹⁰) is often set aside as a typical transition ion.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-143","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Inner transition metals are distinguished from the d-block by the filling of an","options":["ns subshell","np subshell","f subshell","1s subshell"],"answer_index":2,"explanation":"Lanthanoids fill 4f and actinoids fill 5f, so they are the f-block (inner transition) series.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-144","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Including the fourteen lanthanoids, the sixth period contains","options":["eight elements","eighteen elements","thirty-two elements","ten elements"],"answer_index":2,"explanation":"Period 6 fills 6s, 4f, 5d and 6p: 2 + 14 + 10 + 6 = 32.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-145","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Boron heads group 13; the remaining members of that group are best described as","options":["noble gases","metals","halogens","actinoids"],"answer_index":1,"explanation":"Al, Ga, In and Tl are metals; boron is the non-metallic/metalloid head of the group.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-146","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Helium is placed with the noble gases even though its configuration is $1s^{2}$ because","options":["it has an incomplete p subshell","it has a closed shell and is chemically inert","it is an alkali metal","its atomic number is eighteen"],"answer_index":1,"explanation":"A filled 1s shell gives helium the noble-gas chemistry of group 18, not the s-block reactivity of group 2.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-147","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The fourth period contains eighteen elements because the subshells that fill in that period are","options":["4s and 4p only","4s, 3d and 4p","5s, 4d and 5p","4f and 5d only"],"answer_index":1,"explanation":"Capacity 2 + 10 + 6 = 18; 4f is not occupied until period 6.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-148","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The f-block is printed below the main table because inserting the fourteen lanthanoids into period 6 would","options":["violate the modern periodic law","make that row awkwardly wide","change their atomic numbers","turn them into s-block metals"],"answer_index":1,"explanation":"The two-row footnote is a display convention; chemically the lanthanoids still belong in period 6.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-149","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"On moving from left to right across a period, the atomic radius of the elements generally","options":["increases","decreases","remains exactly constant","becomes infinite"],"answer_index":1,"explanation":"Rising effective nuclear charge pulls the same-shell electrons inward, so the atom shrinks.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-150","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"On descending a group, the atomic radius of the elements generally","options":["decreases","increases","becomes zero","is independent of the new shell"],"answer_index":1,"explanation":"Each step down adds a principal shell, which outweighs the extra nuclear charge.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
